// Builds design/export/index.html from design/Main.dc.html.
// Usage: node design/export/build.mjs
// Main.dc.html stays the source of truth. index.html is generated. Do not edit it by hand.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const src = fs.readFileSync(path.join(here, '..', 'Main.dc.html'), 'utf8');
const engine = fs.readFileSync(path.join(here, 'engine.js'), 'utf8');

function grab(re, what) {
  const m = re.exec(src);
  if (!m) throw new Error('Not found in Main.dc.html: ' + what);
  return m[1];
}

const title = grab(/<title>([\s\S]*?)<\/title>/, 'title').trim();
const helmet = grab(/<helmet>([\s\S]*?)<\/helmet>/, 'helmet');
const xdc = grab(/<x-dc>([\s\S]*?)<\/x-dc>/, 'x-dc');
const template = xdc.replace(/<helmet>[\s\S]*?<\/helmet>/, '');
const logic = grab(/<script type="text\/x-dc"[^>]*>([\s\S]*?)<\/script>/, 'logic script');

if (/<\/script/i.test(logic) || /<\/script/i.test(engine)) throw new Error('Script contains a closing script tag');

const out = `<!doctype html>
<!-- GENERATED by design/export/build.mjs from design/Main.dc.html. Do not edit by hand. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
${helmet.trim()}
<style>
sc-if,sc-for{display:contents}
@media (prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}
</style>
</head>
<body>
<div id="app"></div>
<template id="tpl">${template}</template>
<script>
${engine}
</script>
<script>
${logic}
mountDC(Component, '#app', '#tpl');
</script>
</body>
</html>
`;

const dest = path.join(here, 'index.html');
fs.writeFileSync(dest, out);
console.log('Wrote ' + path.relative(process.cwd(), dest) + ' (' + out.length + ' bytes)');
